Create Entity.code:
// Create an Entity so it shows up as a case in follow-up forms.
post(
  // 1) Dataset (entity list) path.
  `v1/projects/${$.configuration.projectId}/datasets/households/entities`,
  // 2) Entity body: uuid, label and dataset property values (strings).
  {
    uuid: $.data.householdUuid,
    label: `${$.data.headOfHousehold} (${$.data.village})`,
    data: {
      head_name: $.data.headOfHousehold,
      village: $.data.village,
      members: String($.data.memberCount),
    },
  }
);

Bulk Create Entities.code:
// Create many Entities at once from an upstream list.
post(
  // 1) Dataset (entity list) path.
  `v1/projects/${$.configuration.projectId}/datasets/patients/entities`,
  // 2) Bulk body: entities plus a source describing where they came from.
  {
    entities: $.data.patients.map(p => ({
      uuid: p.uuid,
      label: `${p.name} (${p.age})`,
      data: { name: p.name, age: String(p.age), facility: p.facility },
    })),
    source: { name: 'emr-export.json', size: $.data.patients.length },
  }
);

Update Entity.code:
// Update properties on an existing Entity.
request(
  // 1) HTTP method.
  'PATCH',
  // 2) Entity path.
  `v1/projects/${$.configuration.projectId}/datasets/patients/entities/${$.data.uuid}`,
  // 3) Fields to change.
  {
    data: { status: 'referred', referral_facility: $.data.facility },
  },
  // 4) force=true skips the baseVersion conflict check.
  { query: { force: true } }
);

Approve Submission.code:
// Mark a submission as approved once it has been synced.
request(
  // 1) HTTP method.
  'PATCH',
  // 2) Submission path.
  `v1/projects/${$.configuration.projectId}/forms/patient-follow-up/submissions/${$.data.__id}`,
  // 3) New review state: approved, hasIssues, rejected or edited.
  { reviewState: 'approved' }
);

Comment On Submission.code:
// Leave a comment on a submission for data managers.
post(
  // 1) Submission comments path.
  `v1/projects/${$.configuration.projectId}/forms/patient-follow-up/submissions/${$.data.__id}/comments`,
  // 2) Comment body.
  { body: 'Could not match this patient ID in the EMR. Please check.' }
);

Create App User.code:
// Create an App User for a new enumerator.
post(`v1/projects/${$.configuration.projectId}/app-users`, {
  displayName: $.data.enumeratorName, // e.g. 'CHW - Kisumu East 04'
});

Get New Submissions.code:
// Fetch submissions received since the last run.
getSubmissions(
  // 1) Project id.
  $.configuration.projectId,
  // 2) Form id (xmlFormId).
  'patient-follow-up',
  // 3) OData query: only submissions after the cursor date.
  {
    $filter: `__system/submissionDate gt ${$.lastRunAt || '2026-10-01T00:00:00.000Z'}`,
  }
);

List Entities.code:
// List Entities (cases) in a dataset via OData.
get(`v1/projects/${$.configuration.projectId}/datasets/patients.svc/Entities`, {
  query: {
    // OData filter on entity properties or system fields.
    $filter: "status eq 'active'",
    $top: 250,
  },
});
